<script setup>
import { ref,computed } from 'vue'
import { useRouter } from 'vue-router'
import { Plus,Download,Wallet,Layers,ChartNoAxesColumn,FileText,Headphones,CreditCard,Landmark } from 'lucide-vue-next'
import { ElMessage } from 'element-plus'
import PageTitle from '../components/PageTitle.vue'
import LedgerTable from '../components/LedgerTable.vue'
import BrandBand from '../components/BrandBand.vue'
import { state,money,exportCsv,stamp,uid } from '../lib/store'
import { requireRole,confirm,notify } from '../lib/actions'
const router=useRouter(),ledger=ref(null),method=ref('online'),dialog=ref(false),amount=ref(1000)
const stats=computed(()=>[{label:'账户余额',cents:state.merchantBalance,icon:Wallet},{label:'托管中',cents:state.tasks.filter(t=>['招募中','进行中','待验收','审核中'].includes(t.status)).reduce((s,t)=>s+t.cents,0),icon:Layers},{label:'累计花费',cents:state.merchantFlows.filter(f=>f.type==='分账').reduce((s,f)=>s+f.cents,0),icon:ChartNoAxesColumn},{label:'待开票',cents:state.merchantFlows.filter(f=>f.type==='分账').reduce((s,f)=>s+f.cents,0),icon:FileText}])
async function recharge(){if(!requireRole(router,'merchant'))return;const cents=Math.round(amount.value*100);if(!Number.isFinite(cents)||cents<100||cents>5000000){ElMessage.warning('演示充值金额须在 ¥1–50,000 之间');return}if(await confirm(`本次仅模拟充值 ¥${money(cents)}，不会从任何账户扣款。`,'演示充值')){state.merchantBalance+=cents;state.merchantFlows.unshift({id:uid('MF'),at:stamp(),type:'充值',title:'演示充值',cents,status:'已完成',ref:uid('DEMO')});dialog.value=false;notify('演示充值记录已保存')}}
</script>
<template><div><PageTitle title="财务管理" description="查看赏金托管、任务结算与每一笔资金记录。"><el-button type="primary" @click="dialog=true"><Plus/>充值</el-button><el-button @click="exportCsv(ledger?.filtered||state.merchantFlows)"><Download/>导出账单</el-button></PageTitle><div class="stat-grid"><section class="stat-card" v-for="s in stats" :key="s.label"><div class="stat-icon"><component :is="s.icon" :size="24"/></div><div><label>{{s.label}}</label><strong class="price-text">¥{{money(s.cents)}}</strong></div></section></div><div class="columns wide-left"><section class="panel"><h2>资金流水</h2><LedgerTable ref="ledger" :rows="state.merchantFlows" merchant/></section><aside class="stack"><section class="panel"><h2>充值</h2><p class="muted small">为任务发布与赏金托管准备资金</p><div class="recharge-methods"><button :class="{selected:method==='online'}" @click="method='online'"><CreditCard/><span><strong>在线支付</strong><small>支付服务接入后使用</small></span><i/></button><button :class="{selected:method==='bank'}" @click="method='bank'"><Landmark/><span><strong>对公转账</strong><small>大额充值请先联系客服</small></span><i/></button></div><el-button type="primary" class="full-button" @click="method==='online'?dialog=true:router.push('/messages?chat=support&role=merchant')">{{method==='online'?'体验演示充值':'联系充值客服'}}</el-button></section><section class="panel"><h2>发票申请</h2><div class="info-note"><FileText/>当前请联系客服线下办理发票申请。</div><el-button plain type="primary" class="full-button" style="margin-top:18px" @click="router.push('/messages?chat=support&role=merchant')"><Headphones/>联系客服</el-button></section></aside></div><BrandBand style="margin:24px 0 0" text="交易资金托管，验收通过后结算。"/><el-dialog v-model="dialog" title="充值 · 前端演示" width="460px" class="refinement-dialog"><div class="app-ui dialog-stack"><p class="info-note">未接入支付服务。这里只增加当前浏览器的示例余额，不发生真实交易。</p><el-form label-position="top"><el-form-item label="演示充值金额（元）"><el-input-number v-model="amount" :min="1" :max="50000" :precision="2" :controls="false"/></el-form-item></el-form></div><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="recharge">确认模拟充值</el-button></template></el-dialog></div></template>
<style scoped>.recharge-methods{display:grid;gap:12px;margin:20px 0}.recharge-methods>button{display:flex;align-items:center;gap:14px;border:1px solid #d4dbe6;border-radius:7px;padding:14px;text-align:left}.recharge-methods>button.selected{border-color:#002bd7;background:#f3f6ff}.recharge-methods strong{display:block;font-size:14px}.recharge-methods small{color:#81899a;font-size:11px}.recharge-methods i{width:15px;height:15px;border:1px solid #a6b1c9;border-radius:50%;margin-left:auto}.recharge-methods .selected i{border:4px solid #002bd7}.stat-card strong{font-size:25px}@media(max-width:1200px){.stat-card strong{font-size:20px}}</style>
